contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Try to Collect amount `withdraw` and assert the relation between balances and ether transfer.
    // We observe only through public getters and address balances. We send no Ether with this call.
    function run(uint withdraw) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // No precondition on withdraw; allow any uint.

        // Read observable state before the call
        uint bal_before = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contract_eth_before = address(c).balance;
        uint self_eth_before = address(this).balance;

        bool reverted;
        c.Collect(withdraw); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint bal_after = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contract_eth_after = address(c).balance;
        uint self_eth_after = address(this).balance;

        // General rule:
        // - If Collect reverted then neither the stored balance nor the contract's ether balance changed.
        // - If Collect succeeded then the stored balance did not increase (cannot be more than before),
        //   and the test contract's ether balance did not increase by more than `withdraw`, and the contract's ether decreased by at most `withdraw`.
        assert(
            (reverted && bal_after == bal_before && contract_eth_after == contract_eth_before && self_eth_after == self_eth_before)
            ||
            (!reverted && bal_after <= bal_before && self_eth_after - self_eth_before <= withdraw && contract_eth_before - contract_eth_after <= withdraw)
        );
    }

    receive() external payable {}
}

