// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 withdraw) internal {
        vm.deal(address(c), VALUE_CAP);
        uint256 bal_before;
        try c.balances(address(this)) returns (uint256 __r) { bal_before = __r; } catch { return; }
        uint contract_eth_before = address(c).balance;
        uint self_eth_before = address(this).balance;
        bool reverted;
        try c.Collect(withdraw) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 bal_after;
        try c.balances(address(this)) returns (uint256 __r) { bal_after = __r; } catch { return; }
        uint contract_eth_after = address(c).balance;
        uint self_eth_after = address(this).balance;
        assertTrue((reverted && bal_after == bal_before && contract_eth_after == contract_eth_before && self_eth_after == self_eth_before)
            ||
            (!reverted && bal_after <= bal_before && self_eth_after - self_eth_before <= withdraw && contract_eth_before - contract_eth_after <= withdraw));
    }

    function testFuzz_run(uint256 withdraw) public {
        _run(withdraw);
    }

    receive() external payable {}
}
